const c_limit = 50;    // shut down test if either temp exceeds (C)
const c_low = 35;      // start derating target amps above this temp (C)
const c_high = 45;     // target amps fully derated to zero at this temp (C)
const idle_watts = 200; // trickle charge grid watts while in IDLE
const fail_watts = 100; // trickle charge grid watts while in FAIL

// Mode dropdown values (Dimming index, order matches switch labels)
const MODES = ['IDLE', 'CHARGE', 'DISCHARGE', 'FAIL', 'STOP'];
const IDLE = 0, CHARGE = 1, DISCHARGE = 2, FAIL = 3, STOP = 4;

// velocity-form PI: nudge grid watts to hold battery amps at target (pure CC)
function updateBatteryWatts(measuredAmps, targetAmps, currentWatts) {
    const Kp = 5;
    const Ki = 1;
    // ignore wobble inside ±2.5A: with 15s-averaged amp samples feeding in,
    // correcting anything tighter just chases noise the inverter has
    // already partly absorbed
    const deadband = 2.5;
    // smallest step the inverter will actually respond to; without this a
    // tiny delta computed just past the deadband gets absorbed silently and
    // the loop never escapes
    const minDelta = 5;
    const maxDelta = 50;
    const wattsMin = -3000;
    const wattsMax = 2400;
    // let each correction land before computing the next, so we don't stack
    // commands the system hasn't responded to yet
    const settleSeconds = 4;

    let lastError = context.get('pid_lastError');
    if (lastError === undefined) lastError = 0;
    let lastUpdate = context.get('pid_lastUpdate') || 0;

    const now = Date.now();
    const dtSinceUpdate = (now - lastUpdate) / 1000;
    if (dtSinceUpdate < settleSeconds) {
        return Math.round(currentWatts);
    }
    // integral accumulates on time between actual updates, not per call
    const dt = Math.min(10, Math.max(0.1, dtSinceUpdate));

    const error = targetAmps - measuredAmps;

    let deltaWatts;
    if (Math.abs(error) < deadband) {
        deltaWatts = 0;
    } else {
        deltaWatts = Kp * (error - lastError) + Ki * error * dt;
    }

    if (deltaWatts > 0 && deltaWatts < minDelta) deltaWatts = minDelta;
    if (deltaWatts < 0 && deltaWatts > -minDelta) deltaWatts = -minDelta;
    if (deltaWatts > maxDelta) deltaWatts = maxDelta;
    if (deltaWatts < -maxDelta) deltaWatts = -maxDelta;

    let newWatts = currentWatts + deltaWatts;
    if (newWatts > wattsMax) newWatts = wattsMax;
    if (newWatts < wattsMin) newWatts = wattsMin;

    context.set('pid_lastError', error);
    context.set('pid_lastUpdate', now);
    return Math.round(newWatts);
}

// store inbound values by topic for persistent reference
let avg_over = 10; // fake average for amps over x iterations
let store = context.get('store') || {};
// the mqtt setpoint feedback only seeds startup inference; after that the
// engine is authoritative -- a stale echo of the previous mode's watts
// arriving just after a transition must not overwrite the new value
if (msg.topic == 'grid' && 'grid' in store && context.get('mode') !== undefined) {
    return null;
}
store[msg.topic] = msg.payload;
if (msg.topic == 'amps') {
    let avg = store['avg'] || 0;
    avg = avg - avg / avg_over + msg.payload / avg_over;
    store['avg'] = parseFloat(avg.toFixed(2));
}
context.set('store', store);

let mode = context.get('mode'); // undefined until Mode arrives after (re)start

let start = context.get('start') || 0;
if (start == 0) {
    start = Date.now();
    context.set('start', start);
}
let elapsed = parseInt((Date.now() - start) / 60000);

let amps = store['amps'];
let avg = store['avg'];
let ah = 'ah' in store ? -store['ah'] : 0;
let volts = store['volts'] || 14.666;
let grid = store['grid'];
let discharge_amps = store['Discharge Amps'] || 0;
let charge_amps = store['Charge Amps'] || 0;

function setGrid(value) {
    store['grid'] = value;
    context.set('store', store);
    node.send({ topic: 'grid', payload: value });
}

function report() {
    return ah.toFixed(1) + " Ah, " + volts + "V, " + amps + "A, " + elapsed + " mins";
}

// switch to a new mode: mirror to the display dropdown, email the status
// to this point, reset the clock and PI state, and set the starting watts
function enterMode(newMode, why, alarm) {
    const prev = (mode === undefined) ? '(none)' : MODES[mode];
    mode = newMode;
    context.set('mode', newMode);
    context.set('start', Date.now());
    context.set('mode_guard', Date.now());
    context.set('pid_lastError', 0);
    context.set('pid_lastUpdate', 0);
    if (newMode == IDLE || newMode == FAIL) {
        // test over: clear the per-test discharge log so the next test
        // counts cycles from 1 and averages only its own battery
        context.set('discharge_history', []);
    }
    node.send({ topic: 'mode', payload: newMode });
    let mail = { title: "Test " + MODES[newMode], payload: prev + " -> " + MODES[newMode] + ": " + why };
    if (alarm) {
        mail.type = 1;
        mail.title = "Test Abort";
    }
    node.send(mail);
    switch (newMode) {
        case IDLE:
            setGrid(idle_watts);
            break;
        case FAIL:
            setGrid(fail_watts);
            break;
        case CHARGE:
        case STOP:
            setGrid(charge_amps > 0 ? charge_amps * 15 : idle_watts);
            break;
        case DISCHARGE:
            setGrid(discharge_amps > 0 ? -discharge_amps * 11 : 0);
            break;
    }
}

// mode selection changes from the display (or echo of our own mirror);
// ignored until startup mode inference below has run, so the dropdown's
// reset-to-IDLE after a redeploy can't kill a test in progress
if (msg.topic == 'Mode') {
    let selected = parseInt(msg.payload);
    if (isNaN(selected) || selected < IDLE || selected > STOP) return null;
    if (mode !== undefined && selected != mode) {
        const now = Date.now();
        // not user input: stale dropdown announcements after a restart, and
        // delayed echoes of our own mirror (the 2s debounces on the Mode
        // output/input nodes) arriving just after an engine transition
        const echo = (now - (context.get('resume_guard') || 0) < 30000) ||
                     (now - (context.get('mode_guard') || 0) < 10000);
        // charge<->discharge flips from the UI are locked out for the first
        // minute of the mode; IDLE and FAIL are always honored
        const flip = ((mode == CHARGE || mode == STOP) && selected == DISCHARGE) ||
                     (mode == DISCHARGE && (selected == CHARGE || selected == STOP));
        if (echo || (flip && elapsed < 1)) {
            node.send({ topic: 'mode', payload: mode }); // push display back
            return null;
        }
        enterMode(selected, "selected on display, was " + report());
    }
    return null;
}

if (mode === undefined) {
    if (!('grid' in store)) {
        node.status({ text: "waiting for grid" });
        return null;
    }
    // presume mode from the persisted grid setpoint so a redeploy resumes
    // the test in progress (STOP is indistinguishable and resumes as CHARGE);
    // IDLE and FAIL trickle at distinct watts so both are retained
    if (grid < 0) mode = DISCHARGE;
    else if (grid == 0 || grid == fail_watts) mode = FAIL;
    else if (grid == idle_watts) mode = IDLE;
    else mode = CHARGE;
    context.set('mode', mode);
    context.set('resume_guard', Date.now());
    node.send({ topic: 'mode', payload: mode }); // sync the display dropdown
    node.send({ title: "Test Resume", payload: "Resumed " + MODES[mode] + " at " + grid + "W after restart" });
}

if (!('amps' in store)) {
    node.status({ text: "waiting for data" });
    return null;
}

// temperature failsafe in every mode except FAIL (IDLE still trickles)
if (mode != FAIL) {
    const sides = ['Positive', 'Negative'];
    for (let i = 0; i < sides.length; i++) {
        let side = sides[i];
        if (side in store && store[side] > c_limit) {
            enterMode(FAIL, side + " terminal at " + store[side] + "C, " + report(), true);
            return null;
        }
    }
}

if (mode == IDLE) {
    node.status({ text: "idle " + avg + " ah=" + ah });
    if (grid != idle_watts) setGrid(idle_watts);
    return null;
}
if (mode == FAIL) {
    // keep the battery topped off, but stop the trickle while over-temp
    let hot = (('Positive' in store && store['Positive'] > c_limit) ||
               ('Negative' in store && store['Negative'] > c_limit));
    let want = hot ? 0 : fail_watts;
    node.status({ text: "fail " + avg + " v=" + volts + " ah=" + ah + (hot ? " HOT" : "") });
    if (grid != want) setGrid(want);
    return null;
}

let target = (mode == DISCHARGE) ? -discharge_amps : charge_amps;

// thermal derating: above c_low, linearly scale the effective target so it
// reaches zero at c_high, shedding heat before the c_limit shutdown; the
// user's amps setting is untouched -- only the value fed to the PI loop
let maxTemp = Math.max('Positive' in store ? store['Positive'] : 0,
    'Negative' in store ? store['Negative'] : 0);
let derate = 1;
if (maxTemp > c_low) {
    derate = Math.max(0, (c_high - maxTemp) / (c_high - c_low));
}

if (target > 0) { // CHARGE or STOP: regulate to +amps until full
    node.status({ text: (mode == STOP ? "stopping " : "charging ") + avg + " e=" + elapsed + " t=" + target });
    // full: at least 1 min in mode, not meaningfully discharging (avg > -1,
    // tolerating ~0 float current and the Cerbo's own draw), charge current
    // tapered off, and the shunt counted consumed Ah back to zero
    if (elapsed >= 1 && avg > -1 && avg < 1.50 && ah == 0) {
        let result = "Charged to " + ah.toFixed(1) + " Ah at " + charge_amps + "A in " + elapsed + " mins";
        if (mode == STOP || discharge_amps <= 0) {
            enterMode(IDLE, result);
        } else {
            enterMode(DISCHARGE, result);
        }
        return null;
    }
} else if (target < 0) { // DISCHARGE: regulate to -amps until empty
    node.status({ text: "discharging " + avg + " v=" + volts + " e=" + elapsed + " t=" + target });
    // empty: at least 1 min in mode, and either the voltage floor was hit or
    // discharge current flowed (avg < -1) and then collapsed (amps > -1);
    // the collapse test is suppressed while derating is active, since backing
    // the target down to zero produces exactly that signature on a good battery
    if (elapsed >= 1 && ((derate == 1 && amps > -1 && avg < -1) || volts < 11.8)) {
        if (ah < 5) {
            // a discharge this short means the battery is not holding a
            // usable charge -- fail instead of cycling endlessly
            enterMode(FAIL, "Discharged only " + ah.toFixed(1) + " Ah at " + discharge_amps +
                "A in " + elapsed + " mins (minimum 5 Ah)", true);
            return null;
        }
        // log this test's discharge Ah readings; length is the cycle count
        let history = context.get('discharge_history') || [];
        history.push(parseFloat(ah));
        while (history.length > 10) {
            history.shift();
        }
        context.set('discharge_history', history);
        let cycle = history.length;
        let last5 = history.slice(-5);
        let avg5 = last5.reduce(function (a, b) { return a + b; }, 0) / last5.length;
        let history_str = history.map(function (v) { return v.toFixed(1); }).join(", ");
        let result = "Discharged to " + ah.toFixed(1) + " Ah at " + discharge_amps + "A in " + elapsed +
            " mins, cycle " + cycle + " of 10, avg(5)=" + avg5.toFixed(1) + " Ah, last 10: [" + history_str + "]";
        // after 10 test cycles, recharge to full and stop instead of cycling
        enterMode(cycle >= 10 ? STOP : CHARGE, result);
        return null;
    }
} else {
    node.status({ text: MODES[mode] + " waiting: amps setting is 0" });
    return null;
}

let pidTarget = target;
if (derate < 1) {
    pidTarget = Math.round(target * derate * 10) / 10;
    node.status({ text: MODES[mode].toLowerCase() + " derated " + target + " -> " + pidTarget + "A (" + maxTemp + "C)" });
}
let newGrid = updateBatteryWatts(amps, pidTarget, grid);
if (newGrid != grid) setGrid(newGrid);
return null;

// ===========================================================================
//  ROLLING AGGREGATOR -- the node's NAME is the expression it evaluates.
// ===========================================================================
//
//  Every incoming message updates a table of "last payload seen, per topic".
//  The node name is then evaluated against that table and the result is sent
//  on. To change what the node computes, RENAME IT -- this body never needs
//  editing. The name doubles as the label on the canvas, so a flow reads as
//  what it does.
//
// ---------------------------------------------------------------------------
//  1. ONE-WORD SHORTHANDS -- name the node any of these and you're done
// ---------------------------------------------------------------------------
//
//    sum       total of the numeric values
//    avg       mean
//    median    middle value
//    min       lowest        max      highest
//    spread    max - min
//    count     how many topics have reported at all
//    latest    the payload that just arrived (this message)
//    topic     the topic that just arrived
//
//    Given topics reporting 2, 4 and 9:
//      name: sum        ->  15
//      name: avg        ->  5
//      name: median     ->  4
//      name: spread     ->  7
//
//    They're ordinary values, so you can do arithmetic on them:
//      name: max - min                 ->  7
//      name: Math.round(avg * 10) / 10 ->  5   (one decimal place)
//      name: sum * 0.98                ->  15 with a 2% derate
//
//    Non-numeric payloads are ignored by sum/avg/median/min/max/spread, so one
//    sensor publishing "offline" can't turn the answer into NaN. With no
//    numbers at all: sum is 0, the rest are NaN.
//
// ---------------------------------------------------------------------------
//  2. TOPIC NAMES AS VARIABLES -- (a + b) / c
// ---------------------------------------------------------------------------
//
//    Topics a, b, c:
//      name: (a + b) / c
//
//    A topic binds to its FULL name, its LAST path segment, or either of those
//    with non-word characters replaced by "_":
//
//      topic                 usable in the name as
//      --------------------  ----------------------------------
//      a                     a
//      solar/pv              pv        solar_pv
//      tank-1/level          level     tank_1_level
//      shop/temp/inside      inside    shop_temp_inside
//
//      name: pv - load                     net power
//      name: (inside + outside) / 2
//      name: tank_1_level > 20 ? 1 : 0
//
//    Only EXACT matches bind. Anything the table doesn't recognise is left
//    alone and resolves as normal JavaScript -- which is precisely what keeps
//    arrow-function parameters working, so the classic idiom below still runs
//    even if you happen to have a topic called "a":
//
//      name: values.reduce((a, b) => a + b, 0) / count
//
//    If two topics share a last segment (foo/level and bar/level), that name
//    is ambiguous and stays unbound -- use the full form (foo_level) instead.
//
// ---------------------------------------------------------------------------
//  3. ${fragment} -- lookup for topics that aren't valid identifiers
// ---------------------------------------------------------------------------
//
//    ${x} matches the topic named exactly x, or failing that, the single topic
//    with x somewhere in it. Unlike section 2, this is a substring search and
//    it is an error -- not a silent zero -- if it matches nothing or matches
//    more than one topic.
//
//      name: (${fwd} + ${aft}) / 2            matches tank/fwd, tank/aft
//      name: ${battery/soc} < 50 ? "low" : "ok"
//
//    pick("x") does the same thing from inside real code, for when you need it
//    somewhere a ${...} can't go:
//
//      name: ["fwd", "aft", "mid"].map(pick).reduce((a, b) => a + b) / 3
//
// ---------------------------------------------------------------------------
//  4. ANYTHING ELSE -- it's a JavaScript expression, so go nuts
// ---------------------------------------------------------------------------
//
//    name: nums.filter(v => v > 50).length          how many are over 50
//    name: nums.every(v => v > 12.0)                all healthy? -> true/false
//    name: count < 3 ? null : avg                   see the note below
//    name: Object.entries(msgs)                     which topic is highest
//            .sort((x, y) => y[1] - x[1])[0][0]
//    name: (max - min) / avg * 100                  % imbalance across a bank
//    name: keys.length + " sensors, " + avg.toFixed(1) + " avg"
//
//    Comments survive, so a bare shorthand can still carry a human label:
//      name: avg /* battery bank mean cell voltage */
//
//    Note on gating: an expression like `count < 3 ? null : avg` still SENDS a
//    message, it just carries null. If you need real suppression, filter
//    downstream on payload, or add an early `return null` here.
//
// ---------------------------------------------------------------------------
//  5. FULL VOCABULARY AVAILABLE TO THE EXPRESSION
// ---------------------------------------------------------------------------
//
//    msgs      { topic: value } -- the whole table
//    keys      topic names          values   payloads, raw and in topic order
//    nums      just the finite numbers       sorted   nums, ascending
//    count     keys.length
//    sum avg median min max spread           over nums (see section 1)
//    latest    this message's payload        topic    this message's topic
//    pick(f)   fuzzy topic lookup (section 3)
//
//    These names win over topic-derived ones: a topic called "count" has to be
//    reached as ${count} or msgs["count"].
//
// ---------------------------------------------------------------------------
//  6. HOUSEKEEPING
// ---------------------------------------------------------------------------
//
//    Send msg.reset (any truthy value) to empty the table without redeploying.
//    Set STALE_MS below to forget topics that have gone quiet.
//
// ===========================================================================

// ---- config ---------------------------------------------------------------

// Forget a topic that hasn't reported for this long, so a sensor that dies
// stops dragging the average toward its last reading. 0 disables the sweep.
const STALE_MS = 0;

// Names the expression gets for free. Listed here rather than inline so the
// parameter order below can't drift out of step with the call site above.
const VOCAB = ['msgs', 'keys', 'values', 'nums', 'sorted', 'count', 'sum', 'avg',
               'median', 'min', 'max', 'spread', 'latest', 'topic', 'pick'];

// Can't be used as a parameter name -- `new Function('true', ...)` is a syntax
// error, so these must never reach the parameter list even if a topic is
// somehow called "class". Globals are here for a different reason: a topic
// named "Math" shouldn't be allowed to shadow the real one.
const NOT_BINDABLE = new Set([
    'true', 'false', 'null', 'undefined', 'this', 'new', 'typeof', 'instanceof',
    'in', 'of', 'void', 'delete', 'return', 'function', 'class', 'let', 'const',
    'var', 'if', 'else', 'do', 'while', 'for', 'switch', 'case', 'break',
    'continue', 'try', 'catch', 'finally', 'throw', 'yield', 'await', 'async',
    'default', 'extends', 'super', 'arguments', 'eval',
    'Math', 'Number', 'String', 'Boolean', 'Object', 'Array', 'JSON', 'Date',
    'Map', 'Set', 'RegExp', 'Error', 'NaN', 'Infinity', 'isNaN', 'isFinite',
    'parseInt', 'parseFloat'
]);

// ---- guards ---------------------------------------------------------------

if (msg.reset) {
    context.set('store', undefined);
    node.status({ fill: 'grey', shape: 'ring', text: 'reset' });
    return null;
}

// Everything here is keyed by topic, so a topic-less message would otherwise
// accumulate quietly under "undefined". Say so instead.
if (typeof msg.topic !== 'string' || msg.topic === '') {
    node.status({ fill: 'red', shape: 'ring', text: 'message has no topic' });
    return null;
}

// ---- accumulate -----------------------------------------------------------

// store = { topic: { value, at } }. The timestamp lives beside the value so
// the staleness sweep doesn't need a second context key kept in sync with it.
const store = context.get('store') || {};
store[msg.topic] = { value: msg.payload, at: Date.now() };

if (STALE_MS > 0) {
    const cutoff = Date.now() - STALE_MS;
    for (const t of Object.keys(store)) {
        if (store[t].at < cutoff) delete store[t];
    }
}
context.set('store', store);

const msgs = {};
for (const t of Object.keys(store)) msgs[t] = store[t].value;

const keys = Object.keys(msgs);
const values = Object.values(msgs);
const nums = values.filter(v => typeof v === 'number' && Number.isFinite(v));
const sorted = [...nums].sort((a, b) => a - b);

// ---- parse the node name (once) -------------------------------------------

// node.name can only change on a redeploy, and a redeploy builds a fresh node
// with fresh context, so a cached parse can never go stale. Everything in
// `plan` is plain data, so it survives even a disk-backed context store.
let plan = context.get('plan');
if (!plan) {
    plan = parseName(node.name);
    context.set('plan', plan);
}

// ---- resolve ${fragment} placeholders --------------------------------------

// Exact topic wins, else the fragment must appear in exactly one topic. The
// original took the first substring hit in key-insertion order, so adding a
// topic later could silently repoint the expression at a different sensor.
// Refusing to guess is cheaper than debugging that at 2am.
const fragValues = [];
for (const frag of plan.fragments) {
    const hits = matchTopics(frag, keys);
    if (hits.length !== 1) {
        node.status({
            fill: 'red', shape: 'ring',
            text: '${' + frag + '} ' + (hits.length ? 'matches ' + hits.length + ' topics' : 'not seen yet')
        });
        return null;
    }
    fragValues.push(msgs[hits[0]]);
}

// ---- bind bare identifiers that name a topic -------------------------------

// aliases: identifier -> topic, or null where two topics claim the same alias.
const aliases = buildAliases(keys);

// Only identifiers that actually name a topic RIGHT NOW become parameters.
// Everything else is deliberately left out of the parameter list so it keeps
// resolving the way plain JavaScript would -- that's what stops us clobbering
// arrow-function parameters, Math, and friends.
const boundNames = plan.identifiers.filter(id => aliases.get(id)).sort();
const ambiguous = plan.identifiers.filter(id => aliases.has(id) && !aliases.get(id));
const boundValues = boundNames.map(id => msgs[aliases.get(id)]);

// ---- compile ---------------------------------------------------------------

// Keyed on the bound names, because those can only change as new topics turn
// up -- which is a handful of times at startup and then never again. A
// compiled function isn't serialisable, so if the default context store is
// disk-backed this just recompiles each message: slower, still correct.
const key = boundNames.join(',');
let compiled = context.get('compiled');
if (!compiled || compiled.key !== key) {
    try {
        compiled = { key: key, fn: build(plan, boundNames) };
    } catch (err) {
        node.status({ fill: 'red', shape: 'ring', text: 'bad expression: ' + err.message });
        return null;
    }
    context.set('compiled', compiled);
}

// ---- evaluate --------------------------------------------------------------

const sum = nums.reduce((a, b) => a + b, 0);
const mid = sorted.length >> 1;

let result;
try {
    result = compiled.fn(
        msgs, keys, values, nums, sorted,
        keys.length,                                        // count
        sum,
        nums.length ? sum / nums.length : NaN,              // avg
        sorted.length                                       // median
            ? (sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2)
            : NaN,
        sorted.length ? sorted[0] : NaN,                    // min
        sorted.length ? sorted[sorted.length - 1] : NaN,    // max
        sorted.length ? sorted[sorted.length - 1] - sorted[0] : NaN,  // spread
        msg.payload,                                        // latest
        msg.topic,                                          // topic
        frag => {                                           // pick()
            const hits = matchTopics(String(frag), keys);
            if (hits.length !== 1) {
                throw new Error('pick("' + frag + '") matched ' + hits.length + ' topics');
            }
            return msgs[hits[0]];
        },
        ...fragValues,
        ...boundValues
    );
} catch (err) {
    // A ReferenceError here is usually a name that looked like a topic but
    // couldn't be bound, so point at the likely culprit rather than making
    // someone re-read the expression character by character.
    const hint = (err instanceof ReferenceError && ambiguous.length)
        ? ' -- ambiguous topic name(s): ' + ambiguous.join(', ')
        : '';
    node.status({ fill: 'red', shape: 'ring', text: err.message + hint });
    node.error(new Error(err.message + hint), msg);   // so a Catch node sees it
    return null;
}

msg.payload = result;
msg.topic = node.name;   // as before -- swap for a fixed string if carrying
                         // the expression as a topic is awkward downstream

// The expression is already the node's label, so spend the status bar on the
// answer and how many inputs went into it.
const shown = typeof result === 'number' ? String(+result.toFixed(4)) : String(result);
node.status({ fill: 'green', shape: 'dot', text: keys.length + ' topics \u2192 ' + shown.slice(0, 40) });
return msg;

// ===========================================================================
//  helpers -- hoisted, so the interesting code stays at the top of the node
// ===========================================================================

// One pass over the name: pull out ${...} placeholders and note every bare
// identifier that might turn out to be a topic.
function parseName(name) {
    const fragments = [];

    // Placeholders become PARAMETERS, not text pasted into the source. The
    // original substituted values straight into the string before eval, so a
    // string payload of "on" became the bare token `on` (ReferenceError) and
    // anything containing a quote broke the parse.
    const src = name.replace(/\$\{([^}]+)\}/g, (_, frag) => {
        fragments.push(frag.trim());
        return '__f' + (fragments.length - 1);
    });

    // Comments and string literals are matched first so their contents are
    // consumed and can't be mistaken for identifiers; the optional dot prefix
    // catches property access, since `foo` in `x.foo` is not a free name.
    const TOKEN = /\/\*[\s\S]*?\*\/|\/\/[^\n]*|(['"`])(?:\\[\s\S]|(?!\1)[^\\])*\1|(\.\s*)?([A-Za-z_$][\w$]*)/g;
    const identifiers = new Set();
    let m;
    while ((m = TOKEN.exec(src)) !== null) {
        const id = m[3];
        if (!id || m[2]) continue;                  // comment/string, or x.prop
        if (VOCAB.includes(id) || NOT_BINDABLE.has(id)) continue;
        if (/^__f\d+$/.test(id)) continue;          // our own placeholder param
        identifiers.add(id);
    }

    return { src: src, fragments: fragments, identifiers: [...identifiers] };
}

// Every identifier a topic can answer to. A collision poisons the alias to
// null rather than picking a winner -- silently averaging the wrong sensor is
// worse than an error.
function buildAliases(topics) {
    const aliases = new Map();

    const add = (alias, topic) => {
        if (!/^[A-Za-z_$][\w$]*$/.test(alias)) return;
        if (NOT_BINDABLE.has(alias) || VOCAB.includes(alias)) return;
        if (aliases.has(alias) && aliases.get(alias) !== topic) aliases.set(alias, null);
        else aliases.set(alias, topic);
    };

    for (const topic of topics) {
        const leaf = topic.split(/[/.]/).pop();
        add(topic, topic);                          // a
        add(topic.replace(/\W/g, '_'), topic);      // solar/pv  -> solar_pv
        add(leaf, topic);                           // solar/pv  -> pv
        add(leaf.replace(/\W/g, '_'), topic);       // tank-1    -> tank_1
    }
    return aliases;
}

// Shared by ${...} and pick(): exact topic first, then substring.
function matchTopics(fragment, topics) {
    if (topics.includes(fragment)) return [fragment];
    return topics.filter(t => t.includes(fragment));
}

function build(plan, boundNames) {
    // Bodies made by `new Function` run in the sandbox's global scope, so this
    // expression cannot reach msg, node or any local above -- both a safety
    // win over eval and the reason every input is passed in as an argument.
    const params = [
        ...VOCAB,
        ...plan.fragments.map((_, i) => '__f' + i),
        ...boundNames
    ];
    return new Function(...params, '"use strict"; return (' + plan.src + ');');
}

msg.payload = msg.req.query.mac;
if (msg.req.query.pin) msg.pin = msg.req.query.pin;
if (msg.req.query.type) msg.payload = { mac: msg.req.query.mac, type: msg.req.query.type };
return msg;

const seen = flow.get('seen') || [];
seen.push({
    at: new Date().toISOString().substr(11, 8),
    mac: msg.payload.mac,
    name: msg.payload.name,
    rssi: msg.payload.rssi,
    type: msg.payload.type,
});
flow.set('seen', seen.slice(-200));
return null;

msg.statusCode = 500;
msg.payload = { error: (msg.error && msg.error.message) || 'unknown error' };
return msg;
